window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-7701\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουγάϊος</h1><div class=\"entry-meta\"><span>DGP · ordem 497 na letra β · nº geral 7701</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que conta vantagem; fanfarrão. 〈βου- intens., γαίων〉</p></section></article>\n<article id=\"entry-dgp-7702\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουγενής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 498 na letra β · nº geral 7702</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nascido de um touro. 〈βοῦς, γένος〉</p></section></article>\n<article id=\"entry-dgp-7703\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουδόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 499 na letra β · nº geral 7703</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 apropriado para esfolar os bois ♦ ὁ βουδόρος 2 faca para esfolar bois. 〈βούς, δέρω〉</p></section></article>\n<article id=\"entry-dgp-7704\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουζύγιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 500 na letra β · nº geral 7704</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se refere a uma junta de bois. 〈βοῦς, ζεύγνυμι〉</p></section></article>\n<article id=\"entry-dgp-7705\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουθερής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 501 na letra β · nº geral 7705</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">onde os bois pastam no verão. 〈βοῦς, θέρος〉</p></section></article>\n<article id=\"entry-dgp-7706\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουθόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 502 na letra β · nº geral 7706</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que cobre as novilhas. 〈βοῦς, θρῴσκω〉</p></section></article>\n<article id=\"entry-dgp-7707\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουθρέμμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 503 na letra β · nº geral 7707</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος que alimenta os bois. 〈βοῦς, τρέφω〉</p></section></article>\n<article id=\"entry-dgp-7708\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουθυτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 504 na letra β · nº geral 7708</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut βουθυτήσω) 1 sacrificar bois 2 sacrificar. 〈βούθυτος〉</p></section></article>\n<article id=\"entry-dgp-7709\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βούθυτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 505 na letra β · nº geral 7709</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 concernente ao sacrifício de bois 2 em que se imolam bois. 〈βοῦς, θύω〉</p></section></article>\n<article id=\"entry-dgp-7710\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βούκερως, ως, ων</h1><div class=\"entry-meta\"><span>DGP · ordem 506 na letra β · nº geral 7710</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ω que tem chifres de touro ou de vaca. 〈βοῦς, κέρας〉</p></section></article>\n<article id=\"entry-dgp-7711\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουκολέεσκες</h1><div class=\"entry-meta\"><span>DGP · ordem 507 na letra β · nº geral 7711</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. impf. iter. de βουκολέω.</p></section></article>\n<article id=\"entry-dgp-7712\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουκολέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 508 na letra β · nº geral 7712</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. βουκολήσω, aor. ἐβουκόλησα, perf. desus.; pas. perf. βεβουκόλημαι) 1 fazer pastar: β. βοῦς hom. fazer bois pastarem 2 enganar: β. τὸ δήμιον ar. iludir o povinho 3 dar como alimento algo, ac., a, dat.: ἐβου­κολοῦμεν φροντίσιν νέον πάθος ésql. um novo sofrimento dávamos como alimento às preocupações 4 honrar de modo servil: τὸν αὐτὸν ἄρ’ ἐμοὶ βουκολεῖς Σαβάζιον ar. serves o mesmo Sabázio que eu ♦ méd. 5 fazer pastar: β. αἷγας eup. conduzir cabras ao pasto, β. πόνον ésql. alimentar em si um sofrimento 6 intr. pastar: ῥίψας με βουκολήσεται ar. (o escaravelho) tendo-me derrubado, irá pastar ♦ pas. 7 sustentar-se de; iludir-se com, dat. 〈βουκόλος〉</p></section></article>\n<article id=\"entry-dgp-7713\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουκόλησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 509 na letra β · nº geral 7713</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">guarda de bois. 〈βουκολέω〉</p></section></article>\n<article id=\"entry-dgp-7714\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουκολία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 510 na letra β · nº geral 7714</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 rebanho de gado 2 duv. estábulo. 〈βουκόλος〉</p></section></article>\n<article id=\"entry-dgp-7715\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουκολικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 511 na letra β · nº geral 7715</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pastoril; de poesia bucólica: β. ποίημα poesia bucólica, β. τομή cesura bucólica 2 próprio do pastoreio ♦ τὸ βουκολικόν 3 canto pastoril; poesia bucólica. 〈βουκόλος〉</p></section></article>\n<article id=\"entry-dgp-7716\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουκόλιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 512 na letra β · nº geral 7716</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 rebanho de bois 2 alívio; consolo. 〈βουκόλος〉</p></section></article>\n<article id=\"entry-dgp-7717\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουκόλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 513 na letra β · nº geral 7717</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 guardião de bois; boiadeiro 2 condutor (de animais): β. ἵππων condutor de cavalos. 〈βοῦς, κέλλω〉</p></section></article>\n<article id=\"entry-dgp-7718\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βούκρανος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 514 na letra β · nº geral 7718</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">com cabeça de touro; de boi. 〈βοῦς, κάρηνον〉</p></section></article>\n<article id=\"entry-dgp-7719\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουλά</h1><div class=\"entry-meta\"><span>DGP · ordem 515 na letra β · nº geral 7719</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = βουλή.</p></section></article>\n<article id=\"entry-dgp-7720\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουλαῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 516 na letra β · nº geral 7720</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 do conselho; do senado 2 que aconselha.</p></section></article>\n<article id=\"entry-dgp-7721\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βούλαρχος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 517 na letra β · nº geral 7721</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 presidente do Senado 2 autor de um parecer. 〈βουλή, ἄρχω〉</p></section></article>\n<article id=\"entry-dgp-7722\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βούλει</h1><div class=\"entry-meta\"><span>DGP · ordem 518 na letra β · nº geral 7722</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. pres. ind. de βούλομαι.</p></section></article>\n<article id=\"entry-dgp-7723\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουλευέμεν</h1><div class=\"entry-meta\"><span>DGP · ordem 519 na letra β · nº geral 7723</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. pres. ép. de βουλεύω.</p></section></article>\n<article id=\"entry-dgp-7724\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουλεύησθα</h1><div class=\"entry-meta\"><span>DGP · ordem 520 na letra β · nº geral 7724</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2a sing. pres. subj. ép. de βουλεύω.</p></section></article>\n<article id=\"entry-dgp-7725\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βούλευμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 521 na letra β · nº geral 7725</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 resolução; decisão 2 conselho; parecer. 〈βουλεύω〉</p></section></article>\n<article id=\"entry-dgp-7726\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουλευσέμεν</h1><div class=\"entry-meta\"><span>DGP · ordem 522 na letra β · nº geral 7726</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. fut. ép. de βουλεύω.</p></section></article>\n<article id=\"entry-dgp-7727\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βούλευσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 523 na letra β · nº geral 7727</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 deliberação 2 Jur. βουλεύσεως δίκη ou γραφή processo contra o mandante ou incitador de uma agressão ou morte. 〈βουλεύω〉</p></section></article>\n<article id=\"entry-dgp-7728\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουλευτέον</h1><div class=\"entry-meta\"><span>DGP · ordem 524 na letra β · nº geral 7728</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de βουλεύω.</p></section></article>\n<article id=\"entry-dgp-7729\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουλευτήριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 525 na letra β · nº geral 7729</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tribunal; sala do conselho 2 pl. poét. conselheiros. 〈βουλεύω〉</p></section></article>\n<article id=\"entry-dgp-7730\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουλευτήριος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 526 na letra β · nº geral 7730</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que é conselheiro. 〈βουλεύω〉</p></section></article>\n<article id=\"entry-dgp-7731\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουλευτής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 527 na letra β · nº geral 7731</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 membro de um conselho; em Atenas, membro do Conselho; em Roma, senador 2 rar. conselheiro de algo, gen. 〈βουλεύω〉</p></section></article>\n<article id=\"entry-dgp-7732\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουλευτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 528 na letra β · nº geral 7732</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 relativo a conselhos: νόμοι β. dem. leis relativas ao Conselho 2 relativo a conselheiros: β. ὅρκος xen. juramento dos conselheiros, ἀρχὴ β. artt. dignidade de conselheiro 3 capaz de deliberar, de aconselhar 4 que convém às deliberações ♦ τὸ βουλευτικόν 5 os lugares reservados aos conselheiros (no teatro) 6 tard. a ordem senatorial em Roma 7 a faculdade de deliberar. 〈βουλεύω〉</p></section></article>\n<article id=\"entry-dgp-7733\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουλευτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 529 na letra β · nº geral 7733</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 deliberado; refletido 2 que pode ser deliberado. 〈βουλεύω〉</p></section></article>\n<article id=\"entry-dgp-7734\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουλεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 530 na letra β · nº geral 7734</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. βουλεύσω, aor. ἐβούλευσα, perf. βεβού­λευκα) 1 deliberar em conselho; deliberar: εἰ δέ ποτ’ ἔς γε μίαν βουλεύσομεν hom. se um dia por unanimidade deliberarmos 2 preparar por deliberação; meditar; decidir, ac., inf., ὅπως e subj. ou opt.: β. θάνατόν τινι plat. deliberar a morte de alguém, ἐβούλευε τὸν Δημάρητον παῦσαι τῆς βασιληίης her. ele planejava destituir Demarato da realeza 3 ser membro de um conselho: ἐγὼ γὰρ ἐβούλευσα plat. fui membro do conselho 4 rar. opinar; dar conselhos: τὰ λῷστα β. ésqn. dar os melhores conselhos ♦ méd. 5 ter uma opinião; deliberar: καὶ τοῦτ’ ἀληθές, οὐδὲ βουλεύσῃ πάλιν; sóf. então isso é verdadeiro, e não deliberarás em contrário? κοινῇ βουλευόμενοι xen. deliberando em comum 6 meditar; projetar para si; decidir, ac., inf., or. inter. indir.: β. κακὴν ἀπάτην hom. projetar uma fraude, ἐβουλεύοντο ἐκλιπεῖν τὴν πόλιν her. decidiram abandonar a cidade, ὅπως πρὸς ταῦτα βουλευώμεθα, ὅπως ἂν ἄριστα ἀγωνιζοίμεθα xen. para que decidíssemos como combateríamos melhor ♦ pas. 7 ser objeto de deliberação: τὰ βουλευόμενα xen. as questões em deliberação, τὰ βεβουλευμένα her. as decisões tomadas. 〈βουλή〉</p></section></article>\n<article id=\"entry-dgp-7735\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουλή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 531 na letra β · nº geral 7735</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 vontade; determinação 2 resolução; decisão de uma assembléia: θεῶν ὀλοὰς βουλάς hom. funestas decisões dos deuses, ἐν βουλῇ ἔχειν τὰ γενόμενα her. deliberar sobre o que aconteceu 3 reflexão; consideração: οὐδεὶς περὶ τούτων προτίθησιν οὐδαμοῦ βουλήν dem. ninguém; em parte alguma; propõe uma discussão acerca disso, βουλὴν δοῦναι xen. dar oportunidade de refletir 4 conselho; sugestão: βουλῆς γάρ ἐστιν ἔχθιόν γ’ οὐδὲν κακῆς sóf. nada é mais odioso que um mau conselho 5 projeto; desígnio: τοὺς ὅ γε συγκαλέσας πυκινὴν ἀρτύνετο βουλήν hom. tendo-os reunido; combinava um projeto consistente 6 decreto 7 em Atenas, assembléia deliberativa institucional; Conselho: ἡ β. οἱ πεντακόσιοι ésqn. o Conselho dos Quinhentos.</p></section></article>\n<article id=\"entry-dgp-7736\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουλήεις, ήεσσα, ῆεν</h1><div class=\"entry-meta\"><span>DGP · ordem 532 na letra β · nº geral 7736</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de bom conselho; sábio. 〈βουλή〉</p></section></article>\n<article id=\"entry-dgp-7737\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βούλημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 533 na letra β · nº geral 7737</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">projeto; vontade; intenção. 〈βούλομαι〉</p></section></article>\n<article id=\"entry-dgp-7738\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βούλησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 534 na letra β · nº geral 7738</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 vontade; desejo 2 significado: β. ὀνομάτων plat. sentido das palavras. 〈βούλομαι〉</p></section></article>\n<article id=\"entry-dgp-7739\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουλητός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 535 na letra β · nº geral 7739</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que é ou pode ser desejado ♦ τὸ βου­λητόν 2 aquilo que é objeto de desejo. 〈βούλομαι〉</p></section></article>\n<article id=\"entry-dgp-7740\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουληφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 536 na letra β · nº geral 7740</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que tem voz no Conselho 2 bom conselheiro 3 onde se propõe; onde se delibera 4 tard. instigador de, gen. 〈βουλή, φέρω〉</p></section></article>\n<article id=\"entry-dgp-7741\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουλιμίασις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 537 na letra β · nº geral 7741</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mal da fome; bulimia. 〈βουλιμιάω〉</p></section></article>\n<article id=\"entry-dgp-7742\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουλιμιάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 538 na letra β · nº geral 7742</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sofrer de bulimia. 〈βούλιμος〉</p></section></article>\n<article id=\"entry-dgp-7743\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βούλιμος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 539 na letra β · nº geral 7743</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fome insaciável; bulimia. 〈βου- intens., λιμός〉</p></section></article>\n<article id=\"entry-dgp-7744\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βούλιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 540 na letra β · nº geral 7744</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">capaz de uma boa decisão; prudente; sábio. 〈βουλή〉</p></section></article>\n<article id=\"entry-dgp-7745\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βούλομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 541 na letra β · nº geral 7745</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. βουλήσομαι, aor. ἐβουλήθην e ἠβουλήθην, perf. βεβούλημαι) 1 querer; desejar algo, ac., inf., para alguém, dat.: Τρώεσσιν νίκην β. hom. querer a vitória para os troianos, Τρώεσσι κῦδος ὀρέξαι β. hom. desejar propiciar a glória aos troianos 2 preferir. βούλομ’ ἐγὼ λαὸν σῶν ἔμμεναι ἢ ἀπολέσθαι hom. prefiro que o povo seja salvo a que pereça, βουλήσῃ δειλὸς εἷναι μᾶλλον ἤ’ν ἐμοὶ θρασύς sóf. preferirás ser covarde a ser corajoso contra mim, τούτοις δούλοις μᾶλλον βουλήθεντες ἢ φίλοις χρῆσ­θαι xen. tendo preferido tratá-los como escravos a tratá-los como amigos 3 tender a; querer, inf.: ὁ θεὸς ταπεινῶσαι βούλεται xen. a divindade tende a humilhar 4 significar; querer dizer: τί ἡμῖν βούλεται οὗτος ὁ μῦθος; xen. que sentido tem esta história?</p></section></article>\n<article id=\"entry-dgp-7746\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουλυτόνδε</h1><div class=\"entry-meta\"><span>DGP · ordem 542 na letra β · nº geral 7746</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. aproximadamente na hora de soltar os bois. 〈βουλυτός〉</p></section></article>\n<article id=\"entry-dgp-7747\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουλυτός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 543 na letra β · nº geral 7747</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">hora em que se soltam os bois, i.e., o entardecer. 〈βοῦς, λύω〉</p></section></article>\n<article id=\"entry-dgp-7748\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βούνεβρος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 544 na letra β · nº geral 7748</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cervo já crescido. 〈βου- intens., νεβρός〉</p></section></article>\n<article id=\"entry-dgp-7749\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βοῦνις</h1><div class=\"entry-meta\"><span>DGP · ordem 545 na letra β · nº geral 7749</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) (só voc. βοῦνι e ac. βοῦνιν) coberta de colinas. 〈βουνός〉</p></section></article>\n<article id=\"entry-dgp-7750\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουνοειδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 546 na letra β · nº geral 7750</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">semelhante a uma colina. 〈βουνός, εἷδος〉</p></section></article>\n<article id=\"entry-dgp-7751\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βούνομος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 547 na letra β · nº geral 7751</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">onde o gado pasta. 〈βοῦς, νέμω〉</p></section></article>\n<article id=\"entry-dgp-7752\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουνόμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 548 na letra β · nº geral 7752</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que pasta ♦ ὁ βουνόμος 2 pastor. 〈βοῦς, νέμω〉</p></section></article>\n<article id=\"entry-dgp-7753\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουνός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 549 na letra β · nº geral 7753</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">colina; lugar elevado.</p></section></article>\n<article id=\"entry-dgp-7754\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουνώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 550 na letra β · nº geral 7754</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">βουνοειδής.</p></section></article>\n<article id=\"entry-dgp-7755\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουπλήξ, ῆγος (ὁ</h1><div class=\"entry-meta\"><span>DGP · ordem 551 na letra β · nº geral 7755</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἡ) 1 vara para bater nos bois; aguilhão de bois 2 machado para matar bois. 〈βοῦς, πλήσσω〉</p></section></article>\n<article id=\"entry-dgp-7756\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουπόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 552 na letra β · nº geral 7756</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">capaz de trespassar um boi: β. ὀβελός espeto que trespassa um boi. 〈βοῦς, πείρω〉</p></section></article>\n<article id=\"entry-dgp-7757\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βούπρῳρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 553 na letra β · nº geral 7757</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 com cara de boi 2 que começa com a imolação de um boi: ἑκατόμβη β. hecatombe de 100 carneiros precedida da imolação de um boi. 〈βοῦς, πρῷρα〉</p></section></article>\n<article id=\"entry-dgp-7758\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βοῦς</h1><div class=\"entry-meta\"><span>DGP · ordem 554 na letra β · nº geral 7758</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. βοός (ὁ e ἡ) 1 touro; boi: β. ἄρσην ou ταῦρος β. hom. touro, β. ἄγριος búfalo ♦ ἡ βοῦς 2 vaca 3 couro de boi 4 escudo de couro de boi; escudo.</p></section></article>\n<article id=\"entry-dgp-7759\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βούσταθμον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 555 na letra β · nº geral 7759</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">curral. 〈βοῦς, σταθμός〉</p></section></article>\n<article id=\"entry-dgp-7760\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βούσταθμος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 556 na letra β · nº geral 7760</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">βούσταθμον.</p></section></article>\n<article id=\"entry-dgp-7761\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουστασία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 557 na letra β · nº geral 7761</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">βούσταθμον.</p></section></article>\n<article id=\"entry-dgp-7762\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βούτασις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 558 na letra β · nº geral 7762</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">βούσταθμον.</p></section></article>\n<article id=\"entry-dgp-7763\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βούταλις (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 559 na letra β · nº geral 7763</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἀηδών.</p></section></article>\n<article id=\"entry-dgp-7764\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βούτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 560 na letra β · nº geral 7764</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 que concerne a boi; de boi ♦ ὁ βούτης 2 boiadeiro. 〈βοῦς〉</p></section></article>\n<article id=\"entry-dgp-7765\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βούτομον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 561 na letra β · nº geral 7765</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">βούτομος.</p></section></article>\n<article id=\"entry-dgp-7766\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βούτομος, ου (ἡ, ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 562 na letra β · nº geral 7766</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bútomo, junco dos brejos. 〈βοῦς, τέμνω〉</p></section></article>\n<article id=\"entry-dgp-7767\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βούτυρον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 563 na letra β · nº geral 7767</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">manteiga, usada como ungüento. 〈βοῦς, τυρός〉</p></section></article>\n<article id=\"entry-dgp-7768\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουφονέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 564 na letra β · nº geral 7768</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(3a pl. impf. poét. βουφόνεον) matar bois. 〈βουφόνος〉</p></section></article>\n<article id=\"entry-dgp-7769\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουφόνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 565 na letra β · nº geral 7769</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que mata bois; que imola bois 2 lugar onde se imolam bois ♦ ὁ βουφόνος 3 degolador de bois. 〈βοῦς, πεφνεῖν〉</p></section></article>\n<article id=\"entry-dgp-7770\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουφορβέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 566 na letra β · nº geral 7770</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐβουφόρβουν) fazer pastar os bois. 〈βουφορβός〉</p></section></article>\n<article id=\"entry-dgp-7771\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουφόρβια, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 567 na letra β · nº geral 7771</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">rebanho de bois no pasto. 〈βου­φορβός〉</p></section></article>\n<article id=\"entry-dgp-7772\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βουφορβός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 568 na letra β · nº geral 7772</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que nutre os bois ♦ ὁ βουφορβός 2 boiadeiro. 〈βοῦς, φέρβω〉</p></section></article>\n<article id=\"entry-dgp-7773\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βούχιλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 569 na letra β · nº geral 7773</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que produz erva para os rebanhos. 〈βοῦς, χιλός〉</p></section></article>\n<article id=\"entry-dgp-7774\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βοῶν</h1><div class=\"entry-meta\"><span>DGP · ordem 570 na letra β · nº geral 7774</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. pl. de βοῦς e part. pres. de βοάω.</p></section></article>\n<article id=\"entry-dgp-7775\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βοῶπις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 571 na letra β · nº geral 7775</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) de olho de boi; de olhos grandes. 〈βοῦς; ὤψ〉</p></section></article>\n<article id=\"entry-dgp-7776\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βοώτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 572 na letra β · nº geral 7776</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 aquele que lavra com bois 2 Boieiro ou Arcturo, constelação. 〈βοῦς〉</p></section></article>\n<article id=\"entry-dgp-7777\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραβεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 573 na letra β · nº geral 7777</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 árbitro de jogos 2 juiz; árbitro 3 chefe; comandante.</p></section></article>\n<article id=\"entry-dgp-7778\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραβευτής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 574 na letra β · nº geral 7778</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">βραβεύς.</p></section></article>\n<article id=\"entry-dgp-7779\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραβεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 575 na letra β · nº geral 7779</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 presidir como árbitro; presidir; controlar: βρ. τοὺς πολέμους ser árbitro de guerras 2 decidir como chefe: βρ. κρίσεις fazer julgamentos ♦ pas. 3 ser objeto de julgamento; ser concedido por arbitragem. 〈βραβεύς〉</p></section></article>\n<article id=\"entry-dgp-7780\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βράβης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 576 na letra β · nº geral 7780</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">βραβεύς.</p></section></article>\n<article id=\"entry-dgp-7781\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βράγχιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 577 na letra β · nº geral 7781</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 barbatana 2 pl. brânquias; brônquios.</p></section></article>\n<article id=\"entry-dgp-7782\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βράγχος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 578 na letra β · nº geral 7782</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">rouquidão.</p></section></article>\n<article id=\"entry-dgp-7783\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραδεῖα</h1><div class=\"entry-meta\"><span>DGP · ordem 579 na letra β · nº geral 7783</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fem. de βραδύς.</p></section></article>\n<article id=\"entry-dgp-7784\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραδέως</h1><div class=\"entry-meta\"><span>DGP · ordem 580 na letra β · nº geral 7784</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 lentamente 2 tardiamente. 〈βραδύς〉</p></section></article>\n<article id=\"entry-dgp-7785\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραδίων, βράδιον</h1><div class=\"entry-meta\"><span>DGP · ordem 581 na letra β · nº geral 7785</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comp. de βραδύς.</p></section></article>\n<article id=\"entry-dgp-7786\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραδύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 582 na letra β · nº geral 7786</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. βραδυνῶ, aor. ἐβράδυνα, perf. desus.) 1 ir lentamente; ser lento; demorar para, inf.: μὴ βράδυνε sóf. não demores, εἰ βραδύνοιμεν βοῇ ésql. se demorássemos com o socorro ♦ méd. 2 (pessoa) demorar 3 (coisa) fazer-se lentamente ♦ pas. 4 ser adiado. 〈βραδύς〉</p></section></article>\n<article id=\"entry-dgp-7787\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραδυπλοέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 583 na letra β · nº geral 7787</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. navegar lentamente. 〈βραδύς, πλόος〉</p></section></article>\n<article id=\"entry-dgp-7788\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραδυπορέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 584 na letra β · nº geral 7788</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">avançar lentamente. 〈βραδυπόρος〉</p></section></article>\n<article id=\"entry-dgp-7789\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραδυπόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 585 na letra β · nº geral 7789</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lento 2 que passa com lentidão (alimento, humores). 〈βραδύς, πόρος〉</p></section></article>\n<article id=\"entry-dgp-7790\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραδύπορος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 586 na letra β · nº geral 7790</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">difícil de cruzar; de transpor.</p></section></article>\n<article id=\"entry-dgp-7791\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραδύπους, ους, ουν</h1><div class=\"entry-meta\"><span>DGP · ordem 587 na letra β · nº geral 7791</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ποδος de pés vagarosos. 〈βραδύς, πούς〉</p></section></article>\n<article id=\"entry-dgp-7792\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραδύς, εῖα, ύ</h1><div class=\"entry-meta\"><span>DGP · ordem 588 na letra β · nº geral 7792</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(comp. βραδύτερος e βραδίων, poét. βαρ­δύτερος; superl. βραδύτατος, poét. βάρδιστος) 1 lento; vagaroso: βρ. λέγειν eur. lento para falar 2 lento; lerdo de espírito: βρ. προνοῆσαι tuc. lento para prever 3 (tempo) tardio ♦ τὸ βραδύ 4 morosidade.</p></section></article>\n<article id=\"entry-dgp-7793\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραδυτής, ῆτος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 589 na letra β · nº geral 7793</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lentidão; indolência. 〈βραδύς〉</p></section></article>\n<article id=\"entry-dgp-7794\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βράσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 590 na letra β · nº geral 7794</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. βράττω (fut. desus., aor. ἔβρασα; pas. aor. ἐβράσθην, perf. βέβρασμαι) 1 sacudir; arremessar; rejeitar (do mar para a margem) 2 lançar para o alto para que caia na peneira; peneirar; joeirar ♦ at. e méd. 3 ter agitação convulsiva; (líquido) ferver; borbulhar; fermentar.</p></section></article>\n<article id=\"entry-dgp-7795\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βράσσων</h1><div class=\"entry-meta\"><span>DGP · ordem 591 na letra β · nº geral 7795</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comp. de βραχύς.</p></section></article>\n<article id=\"entry-dgp-7796\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βράττω</h1><div class=\"entry-meta\"><span>DGP · ordem 592 na letra β · nº geral 7796</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = βράσσω</p></section></article>\n<article id=\"entry-dgp-7797\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βράχεα</h1><div class=\"entry-meta\"><span>DGP · ordem 593 na letra β · nº geral 7797</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pl n. de βράχος.</p></section></article>\n<article id=\"entry-dgp-7798\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραχέα</h1><div class=\"entry-meta\"><span>DGP · ordem 594 na letra β · nº geral 7798</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fem. jôn. de βραχύς e pl. de βραχύ.</p></section></article>\n<article id=\"entry-dgp-7799\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραχέως</h1><div class=\"entry-meta\"><span>DGP · ordem 595 na letra β · nº geral 7799</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em pouco tempo; em poucas palavras; brevemente. 〈βραχύς〉</p></section></article>\n<article id=\"entry-dgp-7800\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραχιονιστήρ, ῆρος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 596 na letra β · nº geral 7800</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bracelete. 〈βραχίων〉</p></section></article>\n";
